import collections

def transform(grid):
    if not grid:
        return grid

    # Identify background color (most frequent)
    counter = collections.Counter()
    for row in grid:
        for val in row:
            counter[val] += 1
    bg_color = counter.most_common(1)[0][0]

    h = len(grid)
    w = len(grid[0])

    target_color = None
    max_pixels = 0
    bb = None

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg_color:
                continue

            start_color = grid[r][c]
            nodes = [(r, c)]
            visited = {(r, c)}

            idx = 0
            while idx < len(nodes):
                curr_r, curr_c = nodes[idx]
                idx += 1

                for dr, dc in directions:
                    nr, nc = curr_r + dr, curr_c + dc
                    if 0 <= nr < h and 0 <= nc < w:
                        if grid[nr][nc] == start_color and (nr, nc) not in visited:
                            visited.add((nr, nc))
                            nodes.append((nr, nc))

            if len(nodes) > max_pixels:
                max_pixels = len(nodes)
                target_color = start_color
                rs = min(p[0] for p in nodes)
                cs = min(p[1] for p in nodes)
                re = max(p[0] for p in nodes)
                ce = max(p[1] for p in nodes)
                bb = (rs, cs, re, ce)

    if bb is None:
        return grid

    rs, cs, re, ce = bb

    out_grid = []
    for i in range(re - rs + 1):
        out_row = []
        for j in range(ce - cs + 1):
            val = grid[rs + i][cs + j]
            out_row.append(target_color if val != bg_color else bg_color)
        out_grid.append(out_row)

    return out_grid
